#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using PVZEngine.Tools;
using PVZEngine.Tools.Random;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.prismaticPylon)]
    public class PrismaticPylon : AIEntityBehaviour
    {
        public PrismaticPylon(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicEntityProps.IS_LIGHT_SOURCE, BooleanOperator.Set, LogicContraptionProps.PROP_EVOKED));
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_MASK_FRIENDLY, IntegerOperator.BitOr, EntityCollisionHelper.MASK_PROJECTILE));
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);

            var count = GetKaleidoscopeCount(entity);
            var crystalAlpha = GetCrystalAlpha(entity);
            if (count > 0)
            {
                crystalAlpha = Mathf.Clamp01(crystalAlpha + EVOKED_CRYSTAL_ALPHA_SPEED);
            }
            else
            {
                crystalAlpha = Mathf.Clamp01(crystalAlpha + NOT_EVOKED_CRYSTAL_ALPHA_SPEED);
            }
            SetCrystalAlpha(entity, crystalAlpha);
            entity.SetAnimationFloat("CrystalAlpha", crystalAlpha);
            entity.SetModelProperty("Evoked", count > 0);
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state != EntityCollisionHelper.STATE_ENTER)
                return;
            var entity = collision.Entity;
            var target = collision.Other;
            if (target.Type != EntityTypes.PROJECTILE)
                return;
            if (!entity.IsFriendly(target))
                return;
            if (target.IgnorePrismaticPylon())
                return;
            if (target.IsProjectileColliderIgnored(collision.Collider))
                return;
            var projectileID = entity.GetProjectileID();
            if (!NamespaceID.IsValid(projectileID))
                return;
            var count = GetKaleidoscopeCount(entity);
            if (count > 0)
            {
                TransformProjectileEvoked(entity, target);
                count--;
                SetKaleidoscopeCount(entity, count);
            }
            else
            {
                TransformProjectile(entity, target);
            }
        }
        public static void TransformProjectile(Entity entity, Entity projectile)
        {
            int count = TRANSFORM_COUNT;
            var projectileID = entity.GetProjectileID();
            if (NamespaceID.IsValid(projectileID))
            {
                using var modesItem = ListPool<PrismaticPylonProjectileMode>.Rent();
                var modes = modesItem.Value;
                GetPossibleProjectileModes(entity, projectile, count, modes);
                for (int i = 0; i < count; i++)
                {
                    var mode = modes[i];
                    var position = projectile.Position;
                    var velocity = projectile.Velocity * (1 + (i * 0.25f));
                    mode.Apply(entity, projectileID, projectile, position, velocity);
                }
                projectile.Remove();
            }
        }
        public static void TransformProjectileEvoked(Entity entity, Entity projectile)
        {
            var projectileID = entity.GetProjectileID();
            if (NamespaceID.IsValid(projectileID))
            {

                var position = projectile.Position;

                var count = evokedColorModeIndexes.Length;
                var initialAngle = ANGLE_PER_EVOKED_BULLET * (count - 1) * -0.5f;
                var modes = projectileModes;
                for (int i = 0; i < count; i++)
                {
                    var colorModeIndex = evokedColorModeIndexes[i];
                    var colorMode = modes[colorModeIndex];
                    var angle = initialAngle + ANGLE_PER_EVOKED_BULLET * i;
                    var velocity = projectile.Velocity.RotateClockwiseXZ(angle);
                    var hsv = colorMode.GetHSV(entity, projectile);
                    var lightColor = colorMode.GetLightColor(entity, projectile);

                    using var lightBulletsItem = ListPool<Entity>.Rent();
                    var lightBullets = lightBulletsItem.Value;

                    var bullet = PrismaticPylonProjectileMode.CreateProjectile(entity, projectileID, projectile, position, velocity, hsv, lightColor);
                    if (!bullet.ExistsAndAlive())
                        continue;

                    lightBullets.Add(bullet);
                    foreach (var mode in projectileModes)
                    {
                        mode.ApplyToLight(entity, lightBullets);
                    }
                }
                projectile.Remove();
            }
        }
        public static void GetPossibleProjectileModes(Entity entity, Entity projectile, int count, List<PrismaticPylonProjectileMode> results)
        {
            var rng = entity.RNG;
            projectileModes.RandomTake(count, rng, results);
        }
        public static void SetCrystalAlpha(Entity entity, float value) => entity.SetProperty(PROP_CRYSTAL_ALPHA, value);
        public static float GetCrystalAlpha(Entity entity) => entity.GetProperty<float>(PROP_CRYSTAL_ALPHA);
        public static void SetKaleidoscopeCount(Entity entity, int value) => entity.SetProperty(PROP_KALEIDOSCOPE_COUNT, value);
        public static int GetKaleidoscopeCount(Entity entity) => entity.GetProperty<int>(PROP_KALEIDOSCOPE_COUNT);
        public static void SetTransformerPrism(Entity entity, EntityID? value) => entity.SetProperty(PROP_TRANSFORMER_PRISM, value);
        public static EntityID? GetTransformerPrism(Entity entity) => entity.GetProperty<EntityID>(PROP_TRANSFORMER_PRISM);
        public const int TRANSFORM_COUNT = 3;
        public const float ANGLE_PER_EVOKED_BULLET = -10;
        public const float EVOKED_CRYSTAL_ALPHA_SPEED = 0.1f;
        public const float NOT_EVOKED_CRYSTAL_ALPHA_SPEED = -0.03f;
        public const float EVOCATION_DURATION_SECONDS = 7f;
        public static readonly VanillaBuffPropertyMeta<int> PROP_KALEIDOSCOPE_COUNT = new VanillaBuffPropertyMeta<int>("kaleidoscope_count");
        public static readonly VanillaBuffPropertyMeta<EntityID> PROP_TRANSFORMER_PRISM = new VanillaBuffPropertyMeta<EntityID>("transformer_prism");
        public static readonly VanillaBuffPropertyMeta<float> PROP_CRYSTAL_ALPHA = new VanillaBuffPropertyMeta<float>("crystal_alpha");
        public static readonly int[] evokedColorModeIndexes = new int[]
        {
            0,
            3,
            5
        };
        public static readonly List<PrismaticPylonProjectileMode> projectileModes = new List<PrismaticPylonProjectileMode>()
        {
            new PrismaticPylonProjectileModeRed(),
            new PrismaticPylonProjectileModeOrange(),
            new PrismaticPylonProjectileModeYellow(),
            new PrismaticPylonProjectileModeGreen(),
            new PrismaticPylonProjectileModeCyan(),
            new PrismaticPylonProjectileModeBlue(),
            new PrismaticPylonProjectileModePurple(),
        };
    }
}
